import customers from './customers.json' with {type:'json'};

const TOOL_NAME = 'customer_lookup';

const tool = {
  name: TOOL_NAME,
  description: 'Look up a customer by their customer_id and return their profile.',
  inputSchema: {
    type: 'object',
    properties: {
      customer_id: {
        type: 'string',
        description: 'The unique identifier of the customer to look up.',
      },
    },
    required: ['customer_id'],
    additionalProperties: false,
  },
};

export async function listTools() {
  return [tool];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected a JSON object');
  }

  const keys = Object.keys(args);
  if (!keys.includes('customer_id')) {
    throw new Error('Invalid arguments: "customer_id" is required');
  }
  if (keys.length !== 1) {
    throw new Error('Invalid arguments: only "customer_id" is accepted');
  }

  const { customer_id } = args;
  if (typeof customer_id !== 'string') {
    throw new Error('Invalid arguments: "customer_id" must be a string');
  }
  if (customer_id.length === 0) {
    throw new Error('Invalid arguments: "customer_id" must not be empty');
  }

  const record = customers[customer_id];
  if (!record) {
    throw new Error(`Unknown customer_id: ${customer_id}`);
  }

  const text = `customer_id: ${customer_id}\nname: ${record.name}\ntier: ${record.tier}`;
  return { content: [{ type: 'text', text }] };
}

